import BlockBaseType from "./BlockBaseType";
import { BlockRenderType } from "./BlockRenderType";
import IBlockTypeData from "./IBlockTypeData";
import IJavaBlockTypeData from "./IJavaBlockTypeData";
import MinecraftUtilities from "./MinecraftUtilities";
import Database from "./Database";
import Utilities from "../core/Utilities";
import { EventDispatcher } from "ste-events";
import IFile from "../storage/IFile";
import Log from "../core/Log";
import IComponent from "./IComponent";
import IBlockTypeBehaviorPack from "./IBlockTypeBehaviorPack";
import IBlockTypeWrapper from "./IBlockTypeWrapper";
import IManagedComponentSetItem from "./IManagedComponentSetItem";
import IManagedComponent from "./IManagedComponent";
import { ManagedComponent } from "./ManagedComponent";
import StorageUtilities from "../storage/StorageUtilities";
import { IBlocksMetadataBlockProperty } from "./IBlocksMetadata";
import { IBlockResource } from "./IBlocksCatalog";

export default class BlockType implements IManagedComponentSetItem {
  public data: IBlockTypeData;
  public javaData: IJavaBlockTypeData | null;

  private _baseType?: BlockBaseType;
  private _baseTypeId = "";

  private _isCustom = false;
  private _behaviorPackData: IBlockTypeWrapper | null = null;
  private _behaviorPackFile?: IFile;
  private _blockResource?: IBlockResource;
  private _isLoaded: boolean = false;
  private _loadedWithComments: boolean = false;
  private _properties: { [name: string]: IBlocksMetadataBlockProperty } = {};

  public behaviorPackBlockTypeDef?: IBlockTypeBehaviorPack;
  private _managed: { [id: string]: IManagedComponent | undefined } = {};
  private _onLoaded = new EventDispatcher<BlockType, BlockType>();

  private _onComponentAdded = new EventDispatcher<BlockType, IManagedComponent>();
  private _onComponentRemoved = new EventDispatcher<BlockType, string>();
  private _onComponentChanged = new EventDispatcher<BlockType, IManagedComponent>();

  public get numericId() {
    return this.data.lid;
  }

  public set numericId(newId: number | undefined) {
    this.data.lid = newId;
  }

  public get baseTypeId() {
    return this._baseTypeId;
  }

  public get mapColor(): string | undefined {
    // First check if this specific block type has a map color
    if (this.data.mc) {
      return this.data.mc;
    }

    // Fall back to the base type's map color from mccat.json
    if (this._baseType && this._baseType.mapColor) {
      return this._baseType.mapColor;
    }

    // Check the default base type
    const defaultBaseType = Database.defaultBlockBaseType;
    if (defaultBaseType && defaultBaseType.mapColor) {
      return defaultBaseType.mapColor;
    }

    return undefined;
  }

  public get isCustom() {
    return this._isCustom;
  }

  public get baseType() {
    if (this._baseType !== undefined) {
      return this._baseType;
    }

    return Database.defaultBlockBaseType;
  }

  public get catalogResource(): IBlockResource | undefined {
    if (this._blockResource) {
      return this._blockResource;
    }

    if (Database.blocksCatalog) {
      // First try with shortId (full block name like "acacia_button")
      let lookupId = this.shortId;

      if (lookupId) {
        this._blockResource = Database.blocksCatalog.getCatalogResource(lookupId);
      }

      // Fall back to material if shortId lookup fails
      if (!this._blockResource) {
        let mat = this.material;
        if (mat && mat !== lookupId) {
          this._blockResource = Database.blocksCatalog.getCatalogResource(mat);
        }
      }
    }

    return this._blockResource;
  }

  public set baseType(baseType: BlockBaseType) {
    this._baseType = baseType;
    this._baseTypeId = baseType.name;
  }

  public get material() {
    if (this.data.m) {
      return this.data.m;
    }

    return this.data.n;
  }

  public renderType: BlockRenderType = BlockRenderType.Custom;

  get icon() {
    let val = this.data.ic;

    if (val === undefined && this.baseType !== undefined) {
      val = this.baseType.icon;
    }

    return val;
  }

  get title() {
    let id = this.shortId;

    // For custom blocks, strip the namespace prefix (e.g., "ec_vv:bushy_cherry" -> "bushy_cherry")
    const colonIndex = id.indexOf(":");
    if (colonIndex >= 0) {
      id = id.substring(colonIndex + 1);
    }

    return Utilities.humanifyMinecraftName(id);
  }

  get friendlyName(): string {
    // First check if the base type has a friendly name from mccat.json
    if (this._baseType && this._baseType.friendlyName) {
      return this._baseType.friendlyName;
    }

    // Fall back to humanified shortId
    return this.title;
  }

  constructor(typeId: string) {
    this.javaData = null;

    this.data = {
      n: typeId,
    };

    if (typeId.indexOf(":") >= 0 && !typeId.startsWith("minecraft:")) {
      this._isCustom = true;
    }
  }

  getIcon(): string {
    const icon = this.icon;

    if (icon === undefined) {
      return this.shortId;
    }

    const typeName = MinecraftUtilities.canonicalizeName(this.id);

    const lastUnder = typeName.lastIndexOf("_");

    let allButLast = typeName;

    if (lastUnder >= 0) {
      allButLast = allButLast.substring(0, lastUnder);
    }

    switch (icon) {
      case "st_":
        return "stone_" + allButLast;

      case "le_":
        return "leaves_acacia_carried";

      case "pl_":
        return "planks_" + allButLast;

      case "_car":
        return allButLast + "_carried";

      case "plant_":
        return typeName + "_fern_carried";
      case "_":
        return typeName;

      case "_t":
        return allButLast + "_top";

      case "_br":
        return allButLast + "_bricks";

      case "_carr":
        return typeName + "_carried";

      case "_bl":
        return allButLast + "_block";

      case "_n":
        return allButLast + "_normal";

      case "_blt":
        return allButLast + "_block_top";

      case "mshblk":
        const lastmb = allButLast.split("_");

        return "mushroom_block_skin_" + lastmb[0];

      case "ml_sm":
        const lastml = allButLast.split("_");

        return lastml[lastml.length - 2] + "_" + lastml[lastml.length - 1] + "_smooth";

      case "l_blt":
        const lastbt = allButLast.split("_");

        return lastbt[lastbt.length - 1] + "_block_top";

      case "|":
        return allButLast;

      case "|s":
        return allButLast + "s";

      case "l":
        const last = allButLast.split("_");

        return last[last.length - 1];

      case "sb_":
        const fu = allButLast.split("_");

        return "stonebricks_" + fu[0];

      case "st_l_sm":
        const lasta = allButLast.split("_");

        return "stone_" + lasta[lasta.length - 1] + "_smooth";

      case "|rv":
        // dark_prismarine_stairs => prismarine_dark_stairs
        let result = "";

        const rv = allButLast.split("_");

        for (let i = rv.length - 1; i > 0; i--) {
          if (result.length > 0) {
            result += "_";
          }

          result += rv[i];
        }

        return result;

      case "2rv":
        // yellow_glazed_terracotta => glazed_terracotta_yellow
        // dark_blue_glazed_terracotta => glazed_terracotta_dark_blue
        let resultF = "";

        const rvF = typeName.split("_");

        if (rvF.length >= 2) {
          resultF = rvF[rvF.length - 2] + "_" + rvF[rvF.length - 1];

          for (let i = 0; i < rvF.length - 2; i++) {
            resultF += "_" + rvF[i];
          }
        } else {
          resultF = typeName;
        }

        return resultF;

      case "rv":
        // dark_prismarine => prismarine_dark
        let resultA = "";

        const rvA = typeName.split("_");

        for (let i = rvA.length - 1; i >= 0; i--) {
          if (resultA.length > 0) {
            resultA += "_";
          }

          resultA += rvA[i];
        }

        return resultA;
    }

    if (this.icon !== undefined) {
      return this.icon;
    }

    return this.shortId;
  }

  public get id() {
    if (this.behaviorPackBlockTypeDef && this.behaviorPackBlockTypeDef.description) {
      return this.behaviorPackBlockTypeDef.description.identifier;
    }

    if (this.data.n === undefined) {
      return "";
    }

    if (this.data.n.endsWith("_")) {
      return this.data.n + this.baseTypeId;
    }

    return this.data.n;
  }

  public set id(newId: string) {
    this.data.n = newId;

    if (this.behaviorPackBlockTypeDef && this.behaviorPackBlockTypeDef.description && newId) {
      this.behaviorPackBlockTypeDef.description.identifier = newId;
    }
  }

  public get onComponentAdded() {
    return this._onComponentAdded.asEvent();
  }

  public get onComponentRemoved() {
    return this._onComponentRemoved.asEvent();
  }

  public get onComponentChanged() {
    return this._onComponentChanged.asEvent();
  }

  public get isLoaded() {
    return this._isLoaded;
  }

  public get behaviorPackFile() {
    return this._behaviorPackFile;
  }

  public get onLoaded() {
    return this._onLoaded.asEvent();
  }

  public set behaviorPackFile(newFile: IFile | undefined) {
    this._behaviorPackFile = newFile;
  }

  public get shortId() {
    let id = this.id;
    if (id.startsWith("minecraft:")) {
      return id.substring(10, id.length);
    }

    return id;
  }

  getComponent(id: string) {
    if (this.behaviorPackBlockTypeDef === undefined) {
      return undefined;
    }

    if (!Utilities.isUsableAsObjectKey(id)) {
      Log.unsupportedToken(id);
      throw new Error();
    }

    if (!this._managed[id]) {
      const comp = this.behaviorPackBlockTypeDef.components[id];

      if (comp) {
        this._managed[id] = new ManagedComponent(this.behaviorPackBlockTypeDef.components, id, comp);
      }
    }

    return this._managed[id];
  }

  notifyComponentUpdated(id: string) {
    const component = this.getComponent(id);

    if (component === undefined) {
      Log.unexpectedUndefined("BTNCU");
    } else {
      this._onComponentChanged.dispatch(this, component);
    }
  }

  getAllComponents() {
    return this.getComponents();
  }

  getComponents(): IManagedComponent[] {
    const componentSet: IManagedComponent[] = [];

    if (this.behaviorPackBlockTypeDef !== undefined) {
      for (const componentName in this.behaviorPackBlockTypeDef.components) {
        const component = this.getComponent(componentName);

        if (component !== undefined) {
          componentSet.push(component);
        }
      }
    }

    return componentSet;
  }

  ensurePropertyDefinition(propertyName: string, propertyDef: IBlocksMetadataBlockProperty) {
    if (!this._properties[propertyName]) {
      this._properties[propertyName] = propertyDef;
    }
  }

  addComponent(
    id: string,
    componentOrData: ManagedComponent | IComponent | string | string[] | boolean | number[] | number | undefined
  ) {
    this._ensureBehaviorPackDataInitialized();

    const bpData = this.behaviorPackBlockTypeDef as IBlockTypeBehaviorPack;

    const mc =
      componentOrData instanceof ManagedComponent
        ? componentOrData
        : new ManagedComponent(bpData.components, id, componentOrData);

    bpData.components[id] = mc.getData();
    this._managed[id] = mc;

    this._onComponentAdded.dispatch(this, mc);

    return mc;
  }

  removeComponent(id: string) {
    if (this.behaviorPackBlockTypeDef === undefined) {
      return;
    }

    const newBehaviorPacks: {
      [name: string]: IComponent | string | string[] | boolean | number[] | number | undefined;
    } = {};
    const newComponents: { [name: string]: IManagedComponent | undefined } = {};

    for (const name in this.behaviorPackBlockTypeDef.components) {
      if (name !== id) {
        const component = this.behaviorPackBlockTypeDef.components[name];

        newBehaviorPacks[name] = component;
      }
    }

    for (const name in this._managed) {
      if (name !== id) {
        newComponents[name] = this._managed[name];
      }
    }

    this.behaviorPackBlockTypeDef.components = newBehaviorPacks;
    this._managed = newComponents;
  }

  _ensureBehaviorPackDataInitialized() {
    if (this.behaviorPackBlockTypeDef === undefined) {
      this.behaviorPackBlockTypeDef = {
        description: {
          identifier: "unknown",
        },
        components: {},
        events: {},
      };
    }
  }

  persist(): boolean {
    if (this._behaviorPackFile === undefined) {
      return false;
    }

    Log.assert(this._behaviorPackData !== null, "BTP");

    if (!this._behaviorPackData) {
      return false;
    }

    return this._behaviorPackFile.setObjectContentIfSemanticallyDifferent(this._behaviorPackData);
  }

  /**
   * Loads the definition from the file.
   * @param preserveComments If true, uses comment-preserving JSON parsing for edit/save cycles.
   *                         If false (default), uses efficient standard JSON parsing.
   *                         Can be called again with true to "upgrade" a read-only load to read/write.
   */
  async load(preserveComments: boolean = false) {
    // If already loaded with comments, we have the "best" version - nothing more to do
    if (this._isLoaded && this._loadedWithComments) {
      return;
    }

    // If already loaded without comments and caller doesn't need comments, we're done
    if (this._isLoaded && !preserveComments) {
      return;
    }

    if (this._behaviorPackFile === undefined) {
      return;
    }

    if (!this._behaviorPackFile.isContentLoaded) {
      await this._behaviorPackFile.loadContent();
    }

    if (!this._behaviorPackFile.content || this._behaviorPackFile.content instanceof Uint8Array) {
      this._isLoaded = true;
      this._loadedWithComments = preserveComments;
      this._onLoaded.dispatch(this, this);
      return;
    }

    let data: any = {};

    // Use comment-preserving parser only when needed for editing
    let result = preserveComments
      ? StorageUtilities.getJsonObjectWithComments(this._behaviorPackFile)
      : StorageUtilities.getJsonObject(this._behaviorPackFile);

    if (result) {
      data = result;
    }

    this._behaviorPackData = data;

    const block = data["minecraft:block"];

    if (block.description) {
      this.id = block.description.identifier;
    }

    this.behaviorPackBlockTypeDef = block;

    this._isLoaded = true;
    this._loadedWithComments = preserveComments;

    this._onLoaded.dispatch(this, this);
  }
}
